tick.old:
{
    const target = chestOpen ? 1 : 0;
    chestV += (target - chestP) * 0.02;
    chestV *= 0.9;
    chestP += chestV;
    chestLid.rotation.x = -1.25 * chestP;
    chestGem.visible = chestP > 0.3;
    if (chestGem.visible) {
        chestGem.position.y = 0.11 + Math.sin(time * 2.5) * 0.008 + chestP * 0.015;
        chestGem.rotation.y = time * 1.2;
    }
}

